110→    fn build_transaction_insert(
111→        chunk: &[Transaction],
112→    ) -> anyhow::Result<(String, sqlx::postgres::PgArguments)> {
113→        let mut query = String::from(
114→            "INSERT INTO transactions (id, user_id, wallet_address, timestamp, tx_hash, chain, raw_metadata) VALUES ",
115→        );
116→        let mut args = sqlx::postgres::PgArguments::default();
117→        for (i, tx) in chunk.iter().enumerate() {
118→            let chain_str = chain_to_str(&tx.chain);
119→            let base = i * 7;
120→            if i > 0 {
121→                query.push_str(", ");
122→            }
123→            query.push_str(&format!(
124→                "(${}, ${}, ${}, ${}, ${}, ${}::chain_enum, ${})",
125→                base + 1,
126→                base + 2,
127→                base + 3,
128→                base + 4,
129→                base + 5,
130→                base + 6,
131→                base + 7
132→            ));
133→            use sqlx::Arguments;
134→            args.add(tx.id).map_err(|e| anyhow::anyhow!("{e}"))?;
135→            args.add(tx.user_id).map_err(|e| anyhow::anyhow!("{e}"))?;
136→            args.add(&tx.wallet_address)
137→                .map_err(|e| anyhow::anyhow!("{e}"))?;
138→            args.add(tx.timestamp).map_err(|e| anyhow::anyhow!("{e}"))?;
139→            args.add(&tx.tx_hash).map_err(|e| anyhow::anyhow!("{e}"))?;
140→            args.add(chain_str).map_err(|e| anyhow::anyhow!("{e}"))?;
141→            args.add(&tx.raw_metadata)
142→                .map_err(|e| anyhow::anyhow!("{e}"))?;
143→        }
144→        query.push_str(" ON CONFLICT (chain, tx_hash) DO NOTHING");
145→        Ok((query, args))
146→    }
