312→            sql.push_str(&format!(" AND t.timestamp <= ${param_idx}"));
313→        }
314→        sql.push_str(" ORDER BY l.created_at ASC LIMIT $2 OFFSET $3");
315→
316→        let mut query = sqlx::query(&sql).bind(wallet).bind(limit).bind(offset);
317→        if let Some(f) = from {
318→            query = query.bind(f);
319→        }
