344→    pub async fn get_balances(
345→        &self,
346→        wallet: &str,
347→        at: Option<i64>,
348→    ) -> anyhow::Result<Vec<(String, bigdecimal::BigDecimal)>> {
349→        let rows = match at {
350→            Some(ts) => {
351→                sqlx::query(
352→                    r#"
353→                    SELECT le.asset_symbol, SUM(le.amount) as balance
354→                    FROM ledger_entries le
355→                    JOIN transactions t ON le.transaction_id = t.id
356→                    WHERE le.wallet_address = $1 AND t.timestamp <= $2
357→                    GROUP BY le.asset_symbol
358→                    HAVING SUM(le.amount) != 0
359→                    ORDER BY le.asset_symbol
360→                    "#,
361→                )
362→                .bind(wallet)
363→                .bind(ts)
364→                .fetch_all(&self.pool)
365→                .await?
366→            }
367→            None => {
368→                sqlx::query(
369→                    r#"
370→                    SELECT asset_symbol, SUM(amount) as balance
371→                    FROM ledger_entries
372→                    WHERE wallet_address = $1
373→                    GROUP BY asset_symbol
374→                    HAVING SUM(amount) != 0
375→                    ORDER BY asset_symbol
376→                    "#,
377→                )
378→                .bind(wallet)
379→                .fetch_all(&self.pool)
380→                .await?
381→            }
382→        };
383→
384→        let mut balances = Vec::new();
385→        for row in rows {
386→            balances.push((
387→                row.try_get::<String, _>("asset_symbol")?,
388→                row.try_get::<bigdecimal::BigDecimal, _>("balance")?,
